async function createEvidenceRequest(db:any,c:any,r:AuditActionRequest,values:Row,titleFallback='Pièce demandée'){await mustWrite(await db.from('angelcare360_audit_evidence_requests').insert({school_id:c.school.id,title:txt(values.title,titleFallback),reason:txt(values.reason,'Vérification institutionnelle'),responsible_id:isUuid(values.responsible_id)?values.responsible_id:null,responsible_label:txt(values.responsible_label)||null,due_at:txt(values.due_at)||null,accepted_format:txt(values.accepted_format)||null,sensitivity:txt(values.sensitivity,'internal'),state:'open',created_by:c.user.id,created_at:iso(),updated_at:iso()}),'La demande de preuve n’a pas pu être créée.')}
